// Auto's special rule for braced initializers
auto x = {11, 23, 9}; // type of x is std::initializer_list<int>

// Template type deduction does not have this special rule
template<typename T>
void f(T param);       // param's type is deduced

// f({1, 2, 3});      // Error! Can't deduce T for {1, 2, 3}

// Auto in a C++14 return type uses template deduction rules
auto createInitList()
{ 
  // return {1, 2, 3}; // Error! Can't deduce return type
}
